class Solution {
  public int minOperations(int[] nums) {
    int max = 0;
    for (int v : nums) max = Math.max(max, v);
    int[] spf = new int[max + 1];
    for (int i = 2; i <= max; i++) {
      if (spf[i] != 0) continue;
      for (int j = i; j <= max; j += i) if (spf[j] == 0) spf[j] = i;
    }
    int ops = 0, prev = nums[nums.length - 1];
    for (int i = nums.length - 2; i >= 0; i--) {
      int v = nums[i];
      if (v > prev) {
        v = spf[v];
        ops++;
        if (v > prev) return -1;
      }
      prev = v;
    }
    return ops;
  }
}
